from itertools import product

def get_divisors(n):
    if n == 0: return []
    divs = []
    for i in range(1, int(abs(n)**0.5) + 1):
        if n % i == 0:
            divs.append(i)
            divs.append(-i)
            divs.append(n // i)
            divs.append(-(n // i))
    return list(set(divs))

def find_n_good(n, domain_size=5):
    domain = list(range(-domain_size, domain_size + 1))
    total_good_functions = 0
    for c in [0, 2]:
        g_values = {0: c, 1: 1}
        remaining_x = [x for x in domain if x not in g_values]

        def solve(idx, current_g):
            if idx == len(remaining_x):
                return 1
            x = remaining_x[idx]
            count = 0
            if x**n == 0:
                candidates = [c]
            else:
                divs_xn = get_divisors(x**n)
                candidates = [d + c for d in divs_xn]

            filtered_candidates = []
            for val in candidates:
                diff1 = val - 1
                rhs1 = x**n - 1
                if diff1 == 0:
                    if rhs1 != 0: continue
                elif rhs1 % diff1 != 0:
                    continue
                possible = True
                for b, gb in current_g.items():
                    diff = val - gb
                    rhs = x**n - b**n
                    if diff == 0:
                        if rhs != 0:
                            possible = False
                            break
                    elif rhs % diff != 0:
                        possible = False
                        break
                if possible:
                    filtered_candidates.append(val)
            for val in filtered_candidates:
                current_g[x] = val
                count += solve(idx + 1, current_g)
                del current_g[x]
            return count
        total_good_functions += solve(0, g_values)
    return total_good_functions

for n in range(1, 6):
    print(f"N({n}) = {find_n_good(n)}")

