def is_n_good(g, n, limit=10):
    for a in range(-limit, limit + 1):
        for b in range(-limit, limit + 1):
            if a == b: continue
            if (g(a) - g(b)) == 0:
                if a**n - b**n != 0:
                    return False
            elif (a**n - b**n) % (g(a) - g(b)) != 0:
                return False
    return True

